#include <stdio.h>
#include <stdlib.h>

// Define the grid size
#define GRID_SIZE 6

// Define the possible movements (up, down, left, right)
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

// Function to check if a cell is valid
int is_valid(int r, int c) {
    return r >= 0 && r < GRID_SIZE && c >= 0 && c < GRID_SIZE;
}

// Function to perform BFS
void bfs(int sr, int sc, int er, int ec) {
    int visited[GRID_SIZE][GRID_SIZE] = {{0}};
    int dist[GRID_SIZE][GRID_SIZE] = {{0}};
    int q_row[GRID_SIZE * GRID_SIZE], q_col[GRID_SIZE * GRID_SIZE];
    int q_size = 0;

    // Mark the source cell as visited and enqueue it
    visited[sr][sc] = 1;
    dist[sr][sc] = 0;
    q_row[q_size] = sr;
    q_col[q_size] = sc;
    q_size++;

    while (q_size > 0) {
        int r = q_row[0];
        int c = q_col[0];
        q_size--;

        // If this is the destination cell, print the distance and return
        if (r == er && c == ec) {
            printf("dist=%d\n", dist[r][c]);
            return;
        }

        // Explore the neighbors
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            // If the neighbor is valid and not visited, mark it as visited and enqueue it
            if (is_valid(nr, nc) && !visited[nr][nc]) {
                visited[nr][nc] = 1;
                dist[nr][nc] = dist[r][c] + 1;
                q_row[q_size] = nr;
                q_col[q_size] = nc;
                q_size++;
            }
        }
    }

    // If there is no path to the destination, print an error message
    printf("UNREACHABLE\n");
}

int main(int argc, char **argv) {
    if (argc != 5) {
        printf("Usage: %s <sr> <sc> <er> <ec>\n", argv[0]);
        return 1;
    }

    int sr = atoi(argv[1]);
    int sc = atoi(argv[2]);
    int er = atoi(argv[3]);
    int ec = atoi(argv[4]);

    // Check if the source and destination cells are valid
    if (!is_valid(sr, sc) || !is_valid(er, ec)) {
        printf("INVALID_CELL\n");
        return 1;
    }

    // Perform BFS
    bfs(sr, sc, er, ec);

    return 0;
}
